const e={title:"ഞങ്ങൾ കുക്കികൾ ഉപയോഗിക്കുന്നു",description:"ഞങ്ങളുടെ സേവനങ്ങൾ പ്രവർത്തിപ്പിക്കാനും നിങ്ങളെ സൈൻ ഇൻ ആയി നിലനിർത്താനും നിങ്ങളുടെ അനുഭവം മെച്ചപ്പെടുത്താനും ഞങ്ങൾ കുക്കികൾ ഉപയോഗിക്കുന്നു. നിങ്ങൾക്ക് താഴെ നിങ്ങളുടെ മുൻഗണനകൾ നിയന്ത്രിക്കാം.",accept_all:"എല്ലാം സ്വീകരിക്കുക",reject_all:"എല്ലാം നിരസിക്കുക",manage:"മുൻഗണനകൾ നിയന്ത്രിക്കുക",privacy_link:"സ്വകാര്യതാ നയം"},n={title:"കുക്കി മുൻഗണനകൾ",save:"മുൻഗണനകൾ സംരക്ഷിക്കുക",strictly_necessary:{label:"കർശനമായി ആവശ്യമായ",description:"സൈറ്റ് പ്രവർത്തിക്കാൻ ആവശ്യമാണ്. പ്രവർത്തനരഹിതമാക്കാൻ കഴിയില്ല."},functional:{label:"പ്രവർത്തനപരം",description:"നിങ്ങളുടെ ക്രമീകരണങ്ങൾ ഓർക്കുന്നത് പോലുള്ള മെച്ചപ്പെട്ട സവിശേഷതകൾ പ്രാപ്തമാക്കുന്നു."},analytics:{label:"വിശകലനം",description:"സൈറ്റ് മെച്ചപ്പെടുത്താൻ നിങ്ങൾ അത് എങ്ങനെ ഉപയോഗിക്കുന്നു എന്ന് മനസ്സിലാക്കാൻ സഹായിക്കുന്നു."},marketing:{label:"മാർക്കറ്റിംഗ്",description:"പ്രസക്തമായ പരസ്യങ്ങൾ കാണിക്കാനും കാമ്പെയ്‌നുകൾ ട്രാക്ക് ചെയ്യാനും ഉപയോഗിക്കുന്നു."}},t={banner:e,preferences:n};export{e as banner,t as default,n as preferences};
